REPLACE INTO `process_step` (`id`, `step_number`, `title`, `description`, `icon_url`, `created_at`, `updated_at`) VALUES (1,1,'Evaluate','We start by understanding where you stand ??? auditing current skill levels, team capability and the gap between them and the roles you are hiring or training for.',NULL,'2026-09-05 19:55:29','2026-09-05 19:55:29'),(2,2,'Customize','No two institutions need the same programme. The syllabus, delivery mode and schedule are shaped around your cohort rather than pulled off a shelf.',NULL,'2026-09-05 19:55:29','2026-09-05 19:55:29'),(3,3,'Empower','Training runs hands-on with live projects, mentor support and measurable checkpoints, so progress is visible throughout rather than only at the end.',NULL,'2026-09-05 19:55:29','2026-09-05 19:55:29'),(4,4,'Launch','Learners finish placement-ready ??? portfolio built, interviews rehearsed, and connected to our hiring network for the roles the programme was designed around.',NULL,'2026-09-05 19:55:29','2026-09-05 19:55:29');

-- ------------------------------------------------------------
-- Data for table `course` (22 rows)
-- ------------------------------------------------------------
REPLACE INTO `course` (`id`, `name`, `short_description`, `duration_months`, `mode`, `badge`, `badge_text`, `placement_assistance`, `syllabus_url`, `enroll_url`, `is_active`, `display_order`, `created_at`, `updated_at`, `deleted_at`, `icon_url`, `description`, `category`, `role_heading`, `role_intro`, `role_bullets`) VALUES (1,'Python : Full Stack Development','Learning a Python Full Stack course in Coimbatore with LeSuccess offers strong career advantages. Python is a versatile and in-demand language used in software development, data science, and automation. LeSuccess provides quality training covering both basic and advanced concepts. Their focus on live projects and daily tasks helps students gain practical, real-world experience. With 100% placement support, it becomes easier to secure good job opportunities. This course is ideal for both beginners and professionals looking to upgrade their skills.',5,'BOTH','Trending','Trending',1,NULL,NULL,1,1,'2026-09-05 21:01:09','2026-09-21 22:43:28',NULL,NULL,'<p>Python Full Stack Development is one of the most versatile career tracks in modern software engineering.</p>','Python Full Stack','What does a Python Full Stack Developer do?','Python full stack developers build end-to-end web applications, APIs, and scalable backends.','[\"Design scalable REST APIs and database models using Django and PostgreSQL.\",\"Craft interactive, responsive frontends using React and modern CSS.\",\"Deploy production workloads to AWS cloud using Docker containers.\"]'),(2,'Full Stack Java','Java Full Stack development course in Coimbatore - Spring Boot, React and MySQL, with live projects and 100% placement support.',5,'BOTH','MOST_ENROLLED','Most Enrolled',1,'/syllabus/java.pdf','/courses/full-stack-java',1,2,'2026-09-05 21:01:09','2026-09-19 23:24:28',NULL,'/uploads/gallery/654db838-8770-4899-a3fd-e1e8dea40add.jpg','<p>Learning a Java Full Stack course in Coimbatore with LeSuccess offers strong career advantages. Java is still the language most enterprise product teams and service companies in the region hire for, and Spring Boot sits behind the majority of those openings. This course covers core Java properly before moving to frameworks, because the questions that decide an offer are usually about collections, memory and OOP rather than annotations. You build one application across the whole syllabus - front end, REST API, database and deployment - instead of a folder of disconnected exercises. With live projects, daily tasks and 100% placement support, you finish with something you can open in an interview and talk through line by line.</p>','Java Full Stack','What does a Java Full Stack Developer do?','A Java full stack developer owns a feature from the screen a user clicks to the row that lands in the database. That means moving between two quite different skill sets in the same day, and knowing enough about both to make the trade-off between them yourself.','[\"Design the application structure, user interface, APIs, and database schema.\", \"Build the front end, the Spring Boot services behind it, and the queries that feed both.\", \"Ship new features, then keep them fast and stable across browsers and devices.\"]'),(3,'Data Analytics','Turn spreadsheets into decisions - Excel, SQL, Python and Power BI, taught on messy real datasets.',3,'BOTH','OFFER','30% Offer',1,'/syllabus/data-analytics.pdf','/courses/data-analytics',1,3,'2026-09-05 21:01:09','2026-09-20 18:50:50',NULL,'/tech/powerbi.svg','Learning data analytics helps you turn raw numbers into clear answers so you can make smarter, fact-based choices, solve complex problems faster, and boost your career value in almost any industry.','data analytics','What does a Data Analyst do?','Data Analysts transform raw data into meaningful insights that support better business decisions.','[\"Analyze, clean, and visualize data using Python, SQL, Excel, and Power BI.\",\"Build interactive dashboards and reports to identify trends, patterns, and key business insights.\",\"Apply statistical analysis and data-driven techniques to solve real-world business problems.\"]'),(4,'AWS & DevOps','Docker, Kubernetes, Jenkins and Terraform on AWS - build the pipeline that takes code to production.',4,'BOTH','HIGH_DEMAND','High Demand',1,'/syllabus/aws-devops.pdf','/courses/aws-and-devops',1,4,'2026-09-05 21:01:09','2026-09-05 21:01:09',NULL,'/tech/aws.svg',NULL,NULL,NULL,NULL,NULL),(5,'MERN Full Stack','MongoDB, Express, React and Node - one language across the whole stack, with live projects and placement support.',5,'BOTH','BEST_SELLER','Best Seller',1,'/syllabus/mern.pdf','/courses/mern-full-stack',1,5,'2026-09-19 18:20:44','2026-09-19 23:16:34','2026-09-19 20:51:48','/tech/react.svg',NULL,NULL,NULL,NULL,NULL),(6,'MEAN Full Stack','Angular and TypeScript on the front, Node, Express and MongoDB behind it - the stack enterprise teams standardise on.',5,'BOTH',NULL,NULL,1,'/syllabus/mean.pdf','/courses/mean-full-stack',1,5,'2026-09-19 23:16:34','2026-09-22 22:52:35',NULL,'/tech/javascript.svg',NULL,NULL,NULL,NULL,NULL),(7,'C and C++','Learn how a program actually runs - memory, pointers and OOP in C and C++, from first principles.',3,'BOTH',NULL,NULL,1,'/syllabus/c-cpp.pdf','/courses/c-and-cpp',1,6,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/api.svg',NULL,NULL,NULL,NULL,NULL),(8,'DSA with Python / Java','The interview round that filters everyone out - arrays to dynamic programming, in Python or Java, with daily problem practice.',3,'BOTH',NULL,NULL,1,'/syllabus/dsa.pdf','/courses/dsa-with-python-java',1,7,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/python.svg',NULL,NULL,NULL,NULL,NULL),(9,'Data Science','Statistics, Python and machine learning - build models that hold up outside the notebook they were trained in.',4,'BOTH',NULL,NULL,1,'/syllabus/data-science.pdf','/courses/data-science',1,8,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/python.svg',NULL,NULL,NULL,NULL,NULL),(10,'Artificial Intelligence and Machine Learning','From classical machine learning to neural networks - build, train and evaluate models in TensorFlow and PyTorch.',4,'BOTH',NULL,NULL,1,'/syllabus/ai-ml.pdf','/courses/artificial-intelligence-and-machine-learning',1,9,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/python.svg',NULL,NULL,NULL,NULL,NULL),(11,'AWS - The Ultimate','Core AWS services, architecture and cost control - built around the Cloud Practitioner and Solutions Architect exams.',3,'BOTH',NULL,NULL,1,'/syllabus/aws.pdf','/courses/aws-the-ultimate',1,10,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/aws.svg',NULL,NULL,NULL,NULL,NULL),(12,'Frontend Developer - UI/UX Design','Design interfaces in Figma and then build them in React - one course covering both halves of front-end work.',4,'BOTH',NULL,NULL,1,'/syllabus/frontend.pdf','/courses/frontend-developer-ui-ux-design',1,11,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/react.svg',NULL,NULL,NULL,NULL,NULL),(13,'Data Engineering','Build the pipelines analysts depend on - Python, SQL, Spark and Airflow into a cloud warehouse.',4,'BOTH',NULL,NULL,1,'/syllabus/data-engineering.pdf','/courses/data-engineering',1,12,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/mysql.svg',NULL,NULL,NULL,NULL,NULL),(14,'Digital Marketing','SEO, paid ads, content and analytics - run campaigns on real budgets and report on what they returned.',3,'BOTH',NULL,NULL,1,'/syllabus/digital-marketing.pdf','/courses/digital-marketing',1,13,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/api.svg',NULL,NULL,NULL,NULL,NULL),(15,'Gen AI','Work with large language models properly - prompting, APIs, RAG and the limits worth knowing before you ship.',2,'BOTH',NULL,NULL,1,'/syllabus/gen-ai.pdf','/courses/gen-ai',1,14,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/python.svg',NULL,NULL,NULL,NULL,NULL),(16,'Agentic AI','Build AI agents that plan, call tools and finish multi-step work - with the guardrails that keep them usable.',2,'BOTH',NULL,NULL,1,'/syllabus/agentic-ai.pdf','/courses/agentic-ai',1,15,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/python.svg',NULL,NULL,NULL,NULL,NULL),(17,'ServiceNow','Configure and script the ITSM platform large enterprises run their service desks on.',2,'BOTH',NULL,NULL,1,'/syllabus/servicenow.pdf','/courses/servicenow',1,16,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/api.svg',NULL,NULL,NULL,NULL,NULL),(18,'Cybersecurity','Networking, Linux and the security tools behind both defence and ethical hacking - taught in a lab, legally.',2,'BOTH',NULL,NULL,1,'/syllabus/cybersecurity.pdf','/courses/cybersecurity',1,17,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/api.svg',NULL,NULL,NULL,NULL,NULL),(19,'Tally','Tally Prime end to end - ledgers, vouchers, GST, TDS, payroll and the reports an auditor asks for.',2,'BOTH',NULL,NULL,1,'/syllabus/tally.pdf','/courses/tally',1,18,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/excel.svg',NULL,NULL,NULL,NULL,NULL),(20,'Placement Readiness Program','Aptitude, communication, resume and mock interviews - the preparation that turns technical skill into an offer.',3,'BOTH',NULL,NULL,1,'/syllabus/placement-readiness.pdf','/courses/placement-readiness-program',1,19,'2026-09-19 23:16:34','2026-09-21 22:43:28',NULL,'/tech/api.svg',NULL,NULL,NULL,NULL,NULL),(21,'Graphic Design',NULL,3,'BOTH',NULL,NULL,1,NULL,NULL,0,21,'2026-09-20 18:49:29','2026-09-20 18:50:22','2026-09-20 18:50:22',NULL,NULL,NULL,NULL,NULL,NULL),(22,'Photoshop',NULL,3,'BOTH',NULL,NULL,1,NULL,NULL,0,20,'2026-09-21 22:43:10','2026-09-21 22:43:28','2026-09-21 22:43:28',NULL,NULL,NULL,NULL,NULL,NULL);

