llery-4.png',3,4,1,'2026-09-06 16:17:02','2026-09-06 16:47:12','2026-09-06 16:47:12'),(11,'Sri Shanmuga','sri-shanmuga','Full stack selection drive at Sri Shanmugha','/images/gallery/gallery-5.png',3,5,1,'2026-09-06 16:17:02','2026-09-06 16:47:06','2026-09-06 16:47:06'),(12,'SNS','sns','Mega job fair & developer interviews at SNS Institutions','/images/gallery/gallery-6.png',3,6,1,'2026-09-06 16:17:02','2026-09-06 16:46:59','2026-09-06 16:46:59'),(13,'Bishop Heber Trichy','bishop-heber-trichy',NULL,'/uploads/gallery/9965b2ef-d997-47b1-98c7-c976449163e6.jpg',NULL,0,1,'2026-09-06 17:00:55','2026-09-06 18:06:50',NULL),(14,'June 2026','june-2026',NULL,'/uploads/gallery/fa1bf36b-bbdb-4cb8-9bef-bed2f169fb88.png',13,0,1,'2026-09-06 17:01:48','2026-09-06 17:01:48',NULL),(15,'Bishop 2025','bishop-2025',NULL,'/uploads/gallery/82b72117-8775-49e7-a483-cf985b8c3e53.jpg',13,0,1,'2026-09-06 19:28:54','2026-09-06 19:28:54',NULL);

