REPLACE INTO `course_module` (`id`, `course_id`, `title`, `content`, `display_order`, `created_at`, `updated_at`) VALUES (7,2,'Core Java Foundations','Syntax, data types, control flow, arrays, OOP principles, and exception handling.',1,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(8,2,'Java Collections & Streams','List, Set, Map, Generics, Lambdas, and Stream API for data processing.',2,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(9,2,'Database & Hibernate / JPA','Relational database design, SQL queries, JDBC, ORM mapping with Hibernate and Spring Data JPA.',3,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(10,2,'Spring Boot & Microservices','Dependency Injection, Spring MVC, REST APIs, Spring Security with JWT, and microservices architecture.',4,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(11,2,'Frontend Integration with React','Building responsive interfaces, React components, state management, Axios API integration, and user auth.',5,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(16,4,'Linux & Shell Scripting','Linux administration, user permissions, networking basics, and automation scripts.',1,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(17,4,'AWS Cloud Architecture','IAM, EC2, S3, VPC, RDS, Route 53, and auto-scaling cloud infrastructure.',2,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(18,4,'Docker Containerization','Docker images, containers, volumes, multi-stage builds, and Docker Compose.',3,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(19,4,'Kubernetes Orchestration','Pods, Deployments, Services, ConfigMaps, Secrets, Ingress, and Helm charts.',4,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(20,4,'CI/CD with Jenkins & GitHub Actions','Automated build, test, and deployment pipelines, GitOps workflows.',5,'2026-09-05 21:01:09','2026-09-05 21:01:09'),(21,1,'Module 1: Python Core Foundations','[\"Python Syntax & Data Types\",\"OOPs in Python\",\"File I/O & Exception Handling\"]',1,'2026-09-20 00:36:11','2026-09-20 00:36:11'),(22,1,'Module 2: Web Frameworks with Django','[\"Django MVT Architecture\",\"Models & Migrations\",\"REST Framework & Serializers\"]',2,'2026-09-20 00:36:11','2026-09-20 00:36:11'),(23,1,'Module 3: Frontend Mastery with React','[\"React Components & Props\",\"Hooks & State Management\",\"Consuming REST APIs\"]',3,'2026-09-20 00:36:11','2026-09-20 00:36:11'),(36,3,'Advanced Excel for Analysts','[\"Formulas, pivot tables, VLOOKUP/XLOOKUP, data validation, and dashboard creation.\"]',1,'2026-09-20 18:50:50','2026-09-20 18:50:50'),(37,3,'SQL for Data Querying & Analysis','[\"Relational querying, aggregation, window functions, CTEs, and subqueries.\"]',2,'2026-09-20 18:50:50','2026-09-20 18:50:50'),(38,3,'Business Intelligence with Power BI & Tableau','[\"Data modeling, DAX expressions, interactive report authoring, and visualization best practices.\"]',3,'2026-09-20 18:50:50','2026-09-20 18:50:50'),(39,3,'Python for Data Analysis','[\"NumPy, Pandas, Matplotlib, and Seaborn for exploratory data analysis and reporting.\"]',4,'2026-09-20 18:50:50','2026-09-20 18:50:50');

