REPLACE INTO `testimonial` (`id`, `course_id`, `student_name`, `review_text`, `rating`, `source`, `review_date`, `reviewer_role`, `likes_count`, `photo_url`, `display_order`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,1,'Priya S.','The Python Full Stack program was thorough and practical. The hands-on Django and React projects helped me clear technical interviews and land a full-stack role.',5,'Google',NULL,NULL,0,NULL,1,1,'2026-09-05 21:01:09','2026-09-05 21:01:09',NULL),(2,1,'Karthik R.','Excellent mentor guidance and placement support. Building real REST APIs and deploying to the cloud gave me immense confidence.',5,'Google',NULL,NULL,0,NULL,2,1,'2026-09-05 21:01:09','2026-09-05 21:01:09',NULL),(3,2,'Ananya M.','Spring Boot and Microservices concepts were taught clearly with real-world examples. Got placed in a top IT company through LeSuccess placement drives.',5,'Google',NULL,NULL,0,NULL,1,1,'2026-09-05 21:01:09','2026-09-05 21:01:09',NULL),(4,2,'Vignesh K.','Great curriculum covering both Core Java depth and modern Spring Boot ecosystem. Highly recommended for aspiring software engineers.',5,'Google',NULL,NULL,0,NULL,2,1,'2026-09-05 21:01:09','2026-09-05 21:01:09',NULL),(5,3,'Divya B.','The Power BI and SQL modules were phenomenal. Transitioned from non-tech to a Junior Data Analyst role within 3 months of completion.',5,'Google',NULL,NULL,0,NULL,1,1,'2026-09-05 21:01:09','2026-09-05 21:01:09',NULL),(6,4,'Suresh T.','Hands-on AWS and Docker labs made all the difference. The instructors have extensive cloud consulting experience.',5,'Google',NULL,NULL,0,NULL,1,1,'2026-09-05 21:01:09','2026-09-05 21:01:09',NULL),(7,NULL,'Shalini Shalini','I had a great learning experience with Lesuccess. The trainers taught Java, Groovy, and Data Structures & Algorithms in a clear and structured manner. The explanations were easy to understand, and the hands-on exercises helped strengthen my coding foundation.',5,'Google','3 months ago','1 review',1,NULL,1,1,'2026-09-19 17:31:41','2026-09-19 17:31:41',NULL),(8,NULL,'Anu Suhasini','The practical training methodology and supportive mentors at LeSuccess made learning seamless. Concepts were taught from ground up with real-world scenarios that gave me enormous confidence.',5,'Google','3 months ago','2 reviews',0,NULL,2,1,'2026-09-19 17:31:41','2026-09-19 17:31:41',NULL),(9,NULL,'Saranya V.','Joined LeSuccess for the Java Full Stack course. The trainers explain every concept clearly with real coding scenarios, and the live lab sessions helped me grasp backend architecture and Spring Boot with great confidence.',5,'Google','2 months ago','Full Stack Java',2,NULL,3,1,'2026-09-19 17:31:41','2026-09-19 17:31:41',NULL),(10,NULL,'Karthik Raja','Outstanding mentor support and practical teaching methodology! Building REST APIs and deploying applications gave me the exact skills needed to clear technical interviews smoothly.',5,'Google','3 months ago','Python Full Stack',1,NULL,4,1,'2026-09-19 17:31:41','2026-09-19 17:31:41',NULL),(11,NULL,'Divya Bharathi','The Power BI, Advanced Excel, and SQL modules were comprehensive and hands-on. The mentors were patient and guided me through business dashboard projects that helped me transition into a data role.',5,'Google','1 month ago','Data Analytics',3,NULL,5,1,'2026-09-19 17:31:41','2026-09-19 17:31:41',NULL),(12,NULL,'Aravind Kumar','The practical Docker, Kubernetes, and CI/CD pipelines taught here are completely industry-aligned. Trainers are industry practitioners who share real production scenarios. Best IT training institute in Coimbatore!',5,'Google','4 months ago','AWS with DevOps',4,NULL,6,1,'2026-09-19 17:31:41','2026-09-19 17:31:41',NULL);

